    def block_uniform(ar, ac):
        if ar < 0 or ac < 0 or ar + 6 > ROWS or ac + 6 > COLS:
            return None
        ch = grid[ar][ac]
        if ch not in ('b', 'O'):
            return None
        for i in range(ar, ar + 6):
            for j in range(ac, ac + 6):
                if grid[i][j] != ch:
                    return None
        return ch

    target = None
    for ar in range(r - 5, r + 1):
        for ac in range(c - 5, c + 1):
            ch = block_uniform(ar, ac)
            if ch is not None:
                target = (ar, ac, ch)
                break
        if target:
            break

    # Level-completing goal slots (bottom-right cluster)
    goal_slots = {(52, 36), (52, 44), (44, 52), (52, 52), (44, 44), (36, 44)}

