        for j in range(60, 64):
            grid[63][j] = 'O'
        return [''.join(row) for row in grid]

    if target is None:
        return [''.join(row) for row in grid]

    ar, ac, ch = target
    newch = 'O' if ch == 'b' else 'b'
    for i in range(ar, ar + 6):
        for j in range(ac, ac + 6):
            grid[i][j] = newch

